CAT = "fitrkRoad"; SEG = "ROD"
# Traficom picture topics (driving straight, turning, giving way, overtaking, lane changes,
# stopping, parking) for heavy vehicles. Road Traffic Act 729/2018 ss. 20-33, 37-38, 58-61, 102,
# annexes 5.1 and 5.2, and sign descriptions in annex 3.
Q = [
("What is the maximum speed of a truck on a Finnish road, even where signs allow more?",
 "80 km/h", ["90 km/h", "100 km/h", "70 km/h"],
 "Annex 5.1 of the Road Traffic Act sets 80 km/h as a truck's own maximum. A lower sign or general limit always applies when it is lower."),
("You drive a bus not approved for 100 km/h on a motorway signed 120 km/h. What is your top speed?",
 "80 km/h", ["100 km/h", "120 km/h", "90 km/h"],
 "A bus may drive at 80 km/h, or 100 km/h only with the approved special equipment and no standing passengers."),
("A van tows a heavy trailer on the motorway. What is the combination's maximum speed?",
 "80 km/h", ["100 km/h", "60 km/h", "120 km/h"],
 "Annex 5.2: a car with a towed vehicle may do 80 km/h. Only a car or van with a trailer of up to 750 kg may do 100 km/h."),
("What sign must be fixed to the back of a truck whose speed is limited below 80 km/h?",
 "A top speed plate", ["A red triangle", "An orange warning light", "A yellow L plate"],
 "Section 102: a vehicle limited to under 80 km/h carries a speed plate at the rear showing its maximum speed in km/h."),
("The motorway has three lanes in your direction. Which lanes may your truck use?",
 "The two right lanes", ["Any of the three lanes", "Only the left lane", "Only the hard shoulder"],
 "Section 61: on a motorway with three or more lanes each way, a truck or a combination over seven metres long may use only the two right-hand lanes."),
("Your combination is 8 metres long. Does the three-lane motorway rule for trucks apply to it?",
 "Yes, it is over 7 metres", ["No, it is under 12 metres", "Only if it weighs over 12 t", "Only at night"],
 "The two-right-lanes rule covers trucks and any vehicle combination longer than seven metres."),
("To turn left from a narrow road, your long truck must swing briefly into the oncoming lane. What must you do?",
 "Wait until that lane is clear", ["Sound the horn and turn", "Turn quickly to save time", "Flash the lights and go"],
 "A long vehicle may need extra room to turn, but it must not endanger or force oncoming traffic. Wait for a clear gap and turn slowly, checking the mirrors."),
("A round yellow sign with a red border shows a red truck beside a black car. What may you not do in your truck?",
 "Overtake motor vehicles", ["Turn right at junctions", "Stop at the roadside", "Use dipped headlights"],
 "Sign C30 bans overtaking by trucks. It still allows passing two-wheeled motorcycles and mopeds without a sidecar, vehicles waiting in a turning lane and vehicles on a joining lane."),
("A round yellow sign with a red border shows a black bus. What does it mean for your coach?",
 "No entry for buses", ["Bus lane starts", "Bus stop ahead", "Buses have priority"],
 "Sign C9 bans driving with a bus on that road. A blue rectangular sign with a bus marks a bus lane instead."),
("You drive a bus. A blue sign over the lane shows a bus and the word TAXI below it. What is the lane?",
 "Buses and taxis only", ["A taxi rank area", "A lane closed to buses", "A bus parking zone"],
 "A bus lane sign (E9) reserves the lane for buses; TAXI at the bottom of the sign means taxis may use it too."),
("Your bus is at a stop on a road with a 50 km/h limit. You signal to pull out. What must you still do?",
 "Check others are giving way", ["Pull out at once, you have priority", "Wave the cars past first", "Sound the horn and go"],
 "Others approaching must let you go, but you must check the mirrors and pull out only when it is clear they can and do give way."),
("A machine you must move is 4.5 metres wide on its trailer. What is needed before it goes on the road?",
 "A special transport permit", ["Only a wide-load flag", "A second driver on board", "Hazard lights all the way"],
 "Loads beyond the permitted width, height, length or mass travel as a special transport (erikoiskuljetus), which needs a permit and its conditions, such as warning vehicles."),
("Your rigid truck turns right at a tight junction. Where do the rear wheels go?",
 "Inside the front wheels' path", ["Exactly over the front wheel path", "Outside the front wheels", "Onto the opposite lane"],
 "Rear wheels cut inside on a turn (off-tracking). Go forward far enough before turning so they clear the kerb and anyone standing there."),
("A long bus turns sharply left out of a stop. What happens at the rear overhang?",
 "It swings out to the right", ["It lifts off the ground", "It stays in line with the cab", "It swings in to the left"],
 "Behind the rear axle a bus's body swings outwards (tail swing) as it turns. Check the mirror on that side before and during the turn."),
("Your truck's crane has bright work lights fitted. When may they be switched on while you drive on the road?",
 "Only while working on the road", ["Always after dark, for safety", "Whenever it is foggy", "On unlit country roads"],
 "Work and auxiliary lights may not be on while the vehicle is simply driven on the road; the ban does not cover work done on the road itself. They dazzle and confuse other road users."),
("On a country road a car pulls out to pass your slow truck. What does the law require of you?",
 "Keep right, no speeding up", ["Speed up to keep the gap", "Move left to block the car", "Brake hard straight away"],
 "The vehicle being overtaken keeps as far right as possible and must not increase speed or make the overtaking harder."),
("Before a long truck starts overtaking on a two-way road, what must the driver be sure of?",
 "Room and time to finish", ["The car ahead is slower than 70", "The road is dry", "The horn has been used"],
 "A long vehicle needs a long clear stretch. Overtake only where you can see far enough and return without forcing the overtaken vehicle to brake."),
("Where on a motorway may you not stop your truck, apart from emergencies?",
 "Outside signed areas", ["Only on the hard shoulder", "Only near the exits", "Only in the tunnels"],
 "Stopping and parking on a motorway are allowed only at signed parking, service or rest areas, apart from an emergency or giving way."),
("You leave the motorway at an exit that has a long deceleration lane. When should your truck move onto it?",
 "As early as possible", ["At its very end", "After the exit sign only", "Once you have braked hard"],
 "Section 59: where there is a deceleration lane, move onto it as early as you can and slow down there, not in the motorway lane."),
("A blue bus stop sign stands at the kerb with no platform or markings. How close to it may you park your truck?",
 "No closer than 12 metres", ["No closer than 5 metres", "No closer than 30 metres", "Right next to it, if empty"],
 "The bus stop sign E6 bans parking within 12 metres of the sign where there is no platform or marking. You may stop there briefly if it does not hinder buses."),
("A sign shows a red-bordered yellow circle with 20 t. Your truck weighs 18 t and its trailer 16 t. May you go on?",
 "Yes, each vehicle is under 20 t", ["No, the total is 34 t", "Only with the trailer empty", "Only at walking pace"],
 "Sign C24 limits the actual mass of each vehicle, and in a combination it applies to each one separately. A combination limit is shown by sign C25."),
("You want to move into the next lane, but a car is level with your trailer in that lane. What must you do?",
 "Wait until it has passed", ["Signal and move across slowly", "Sound the horn and move", "Brake so it passes faster"],
 "A driver changing lanes must give way to traffic already in the lane. Check the mirrors along the whole length of the combination before moving."),
("Your bus pulls into a stop at the kerb. What should you check in the right-hand mirrors as you pull in?",
 "Cyclists and people at the kerb", ["The number of the next stop", "Traffic on the far side", "Your own rear lights"],
 "As a bus moves towards the kerb, cyclists and pedestrians can be squeezed or struck by the front corner and the body. Check the near-side mirrors and pull in slowly."),
("A sign before an underpass shows a height limit of 4.0 m. Your truck's cab is 3.8 m high, but the load on its bed reaches 4.2 m. May you drive through?",
 "No, the load counts too", ["Yes, the truck is under 4 m", "Yes, if you drive slowly", "Only if the load is soft"],
 "Sign C22 gives the maximum height in metres, and the load is included in the measurement. Find another route."),
("Which lane should a long combination choose before a tight left turn on a multi-lane road?",
 "The left-turn lane", ["The right lane for room", "Straddle two lanes early", "The bus lane"],
 "Position in the lane marked for your direction in good time. If the turn needs more room, take care with traffic beside you but stay in your lane."),
("A continuous yellow line is painted along the kerb at a bus stop in Turku. What does it tell you?",
 "Stopping there is restricted", ["Buses must stop there", "Taxis may park there", "Parking is free for 15 min"],
 "A yellow continuous edge marking shows a stopping restriction linked to a bus or tram stop, or clarifies a ban on stopping or parking."),
("Your loaded truck follows a car on a wet road. Why should your gap be larger than the car driver's?",
 "It takes longer to stop", ["It has fewer forward gears", "It has stronger brakes", "Its lights are higher"],
 "A heavy vehicle's stopping distance is longer and it hides the view ahead. Keep a gap large enough to avoid any risk of a rear-end crash."),
("A motorway slip road joins from the right. Your truck is in the right lane. What helps traffic merge?",
 "Move left if it is safe", ["Speed up to block them", "Stop on the motorway", "Flash your headlights at them"],
 "Joining traffic must give way, but moving to the next lane when it is safe, or adjusting speed, helps them join smoothly."),
]
